module.exports = "<section\n  class=\"bmb_user-summary_content\"\n  [ngClass]=\"getClass('bmb_user-summary_content')\"\n>\n  <bmb-user-image\n    [size]=\"imageSize()\"\n    [image]=\"image()\"\n    [altImage]=\"name()\"\n    [bordered]=\"isImageBordered()\"\n    (buttonClick)=\"handleUserClick($event)\"\n  />\n  <section\n    class=\"bmb_user-summary_content-wrapper\"\n    [ngClass]=\"getClass('bmb_user-summary_content-wrapper')\"\n    bmbLayout\n    [alignItems]=\"contentLayout() === 'column' ? 'center' : 'start'\"\n    [gapSize]=\"gapSize()\"\n    margin=\"none\"\n    [dynamicCols]=\"true\"\n  >\n    <h3\n      class=\"bmb_user-summary_content-wrapper-title\"\n      [ngClass]=\"getSalutationClasses('bmb_user-summary_content-wrapper-title')\"\n      bmbLayoutItem\n      [isDynamicItem]=\"true\"\n    >\n      {{ getName() }}\n    </h3>\n    <span\n      class=\"bmb_user-summary_content-wrapper-general-text\"\n      bmbLayoutItem\n      [isDynamicItem]=\"true\"\n    >\n      {{ userId() }}\n    </span>\n    @if (!!campus()) {\n      <span\n        class=\"bmb_user-summary_content-wrapper-campus\"\n        bmbLayoutItem\n        [isDynamicItem]=\"true\"\n      >\n        {{ campus() }}\n      </span>\n    }\n    @if (!!infoCareer()) {\n      <span\n        class=\"bmb_user-summary_content-wrapper-general-text\"\n        bmbLayoutItem\n        [isDynamicItem]=\"true\"\n      >\n        {{ infoCareer() }}\n      </span>\n    }\n    @if (additionalInfo()) {\n      <span\n        class=\"bmb_user-summary_content-wrapper-general-text\"\n        bmbLayoutItem\n        [isDynamicItem]=\"true\"\n      >\n        {{ additionalInfo() }}\n      </span>\n    }\n    @if (CURP()) {\n      <span\n        class=\"bmb_user-summary_content-wrapper-general-text\"\n        bmbLayoutItem\n        [isDynamicItem]=\"true\"\n      >\n        {{ 'CURP: '.concat(CURP()!) }}\n      </span>\n    }\n    @if (!!email()) {\n      @if (emailAsLink) {\n        <bmb-text-link\n          [textLink]=\"emailAsLink.label\"\n          icon=\"\"\n          [link]=\"emailAsLink.link\"\n          [target]=\"emailAsLink.target!\"\n        />\n      } @else {\n        <span\n          class=\"bmb_user-summary_content-wrapper-email\"\n          bmbLayoutItem\n          [isDynamicItem]=\"true\"\n        >\n          {{ email() }}\n        </span>\n      }\n    }\n    @if (!!role()) {\n      <span\n        class=\"bmb_user-summary_content-wrapper-title\"\n        [ngClass]=\"\n          getSalutationClasses('bmb_user-summary_content-wrapper-title', true)\n        \"\n        bmbLayoutItem\n        [isDynamicItem]=\"true\"\n      >\n        {{ contentLayout() === 'column' ? role().toLocaleUpperCase() : role() }}\n      </span>\n    }\n    @if (idDigital()) {\n      <bmb-text-link\n        class=\"bmb_user-summary_content-wrapper-id-digital\"\n        [link]=\"idDigital() ?? ''\"\n        target=\"_self\"\n      >\n        <bmb-icon icon=\"id_card\" [size]=\"20\"></bmb-icon>\n        <span style=\"margin-left: .25rem;\">ID Digital</span>\n      </bmb-text-link>\n    }\n  </section>\n</section>\n";

